from pathlib import Path
import json,re,html,shutil
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent;C=Path('/tmp/medina-source-cache/endocrinologie/E25')
assert not (D/'source-binding.json').exists(),'Final evidence sealed; never refresh automatically.'
assert (D/'recherche_E25/sources.json').is_file()
ledger=json.loads((D/'source-ledger.json').read_text())['sources'];pops=[];summaries=[]
def w(k,label):return f'<button class="w" data-k="e25-{k}">{label}</button>'
def pop(k,title,body):pops.append(f'<template data-pop="e25-{k}" data-title="{html.escape(title,quote=True)}">{body}</template>')
def table(h,rows):return '<table class="t" data-e25-table="1"><thead><tr>'+''.join('<th>'+x+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def sec(k,title,body,summary):
 anchor='e25-'+str(k);pk='pareto-'+anchor;summaries.append(f'<template data-pop="{pk}" data-title="Essentiel — {html.escape(title,quote=True)}"><p>{summary}</p><p class="ratio" data-cover="{anchor}"></p></template>')
 return f'<section class="ilot" id="{anchor}"><h2><span class="n">{k}</span>{title}</h2>{body}<div class="key"><b>À retenir.</b> {summary}</div><button class="pareto-btn ui" data-k="{pk}">Essentiel de cette partie</button></section>'
S=[]
S.append(sec(1,'Une urgence peut précéder le résultat du dépistage','''<p>Un garçon fictif de onze jours boit moins, vomit et perd du poids. Il paraît somnolent, sa perfusion est mauvaise et la glycémie est basse. Ses organes génitaux externes d’apparence habituelle n’excluent pas une hyperplasie congénitale des surrénales. Une crise surrénalienne avec perte de sel est une hypothèse urgente, même si le dépistage n’est pas encore disponible [S9, S21].</p><p>La priorité est d’évaluer conscience, respiration, circulation, glycémie et électrolytes, d’appeler une équipe pédiatrique urgente et d’administrer le remplacement parentéral approprié sans attendre une confirmation génétique. Les prélèvements hormonaux sont faits avant si cela n’occasionne aucun retard dangereux. Le bilan recherche aussi sepsis et autres causes de choc [S21].</p><p>Le cours relie les situations PROFILES d’organes génitaux atypiques, de pression anormale et de croissance/puberté inhabituelles au raisonnement. Cette correspondance est pédagogique ; les exercices ne sont pas des questions officielles [S20].</p>''','Un garçon peut présenter une perte de sel sans signe génital visible. L’urgence clinique précède la confirmation étiologique [S9, S21].'))
S.append(sec(2,'Définition et formes cliniques','''<p>La catégorie E25 regroupe les anomalies génito-surrénaliennes. Son noyau clinique est l’hyperplasie congénitale des surrénales liée à un déficit enzymatique de la stéroïdogenèse. Le déficit en 21-hydroxylase, dû à des variants de CYP21A2, représente plus de 90 % des formes dans les séries de référence ; ce pourcentage ne décrit pas une fréquence suisse de toute la catégorie [S1, S3, S22].</p><p>La forme classique comprend une forme avec perte de sel et une forme virilisante simple. Toutes deux peuvent manquer de cortisol ; le déficit minéralocorticoïde et son expression clinique varient. La forme non classique possède une activité résiduelle plus importante : elle peut être asymptomatique ou se révéler par pubarche prématurée, hirsutisme, acné, troubles des règles ou difficulté à concevoir. Une révélation tardive ne signifie pas une maladie acquise [S3, S4].</p><p>Les autres déficits ne reproduisent pas tous ce profil. Un déficit en 11β-hydroxylase associe volontiers excès androgénique et hypertension ; un déficit en 17α-hydroxylase/17,20-lyase peut associer hypertension et déficit en stéroïdes sexuels. Les anomalies du transport du cholestérol, de sa transformation initiale ou d’autres enzymes exigent un profil spécialisé [S3].</p>''','Classique ne signifie pas toujours perte de sel ; non classique reste congénital. Le mécanisme enzymatique guide les signes et le traitement [S3].'))
S.append(sec(3,'Épidémiologie : conserver chaque dénominateur','''<p>Le programme suisse de dépistage indique environ un syndrome adrénogénital pour 9000 nouveau-nés. C’est un chiffre d’information du dépistage, pas une mesure actuelle de toutes les anomalies E25, ni de la forme non classique souvent non repérée à la naissance [S9].</p><p>Une étude suisse publiée en 2025 a recherché rétrospectivement les variations du développement sexuel chez les personnes nées de 2000 à 2019, avec dix hôpitaux pédiatriques et huit endocrinologues privés. Parmi 561 patients identifiés, 118 étaient 46,XX ; la fréquence rapportée de l’hyperplasie congénitale 46,XX était d’une pour 7500 filles nouveau-nées. Son dénominateur est celui des filles et son mode de recrutement celui d’une cohorte clinique. On ne la compare donc pas directement au chiffre tous nouveau-nés du dépistage [S7].</p><p>Les recommandations européennes de génétique 2020 rapportent environ une forme classique pour 16 000 naissances dans de nombreuses populations, avec variations entre programmes. La revue systématique 2017 estimait 4,2 % de formes non classiques parmi des femmes sélectionnées pour excès androgénique, avec intervalle de confiance 3,2–5,4 %. Ce chiffre ne s’applique ni à toutes les femmes ni à tous les nouveau-nés suisses [S4, S22].</p><p>Aucune incidence suisse contemporaine de l’ensemble E25 et de chacune de ses formes rares n’est établie dans les lectures. Les chiffres gardent leur population, leur date et leur méthode.</p>''','1/9000 nouveau-nés, 1/7500 filles et 4,2 % de femmes hyperandrogéniques décrivent trois populations différentes [S4, S7, S9].'))
S.append(sec(4,'Du fonctionnement normal aux symptômes','''<p>Le cortex surrénalien transforme le cholestérol en stéroïdes. La zone glomérulée produit l’aldostérone, sous contrôle surtout du système rénine–angiotensine et du potassium ; la zone fasciculée produit le cortisol et la zone réticulée des androgènes. La médulla interne produit des catécholamines. Une maladie corticale ne constitue donc pas une destruction primaire obligatoire de toutes les fonctions médullaires [S3, S19].</p><p>Le cortisol freine l’axe hypothalamo-hypophysaire. Quand sa synthèse est insuffisante, l’hormone corticotrope augmente et stimule le cortex. Dans le déficit en 21-hydroxylase, la 17-hydroxyprogestérone s’accumule et les flux stéroïdiens favorisent les androgènes ; l’hyperplasie est une conséquence de la stimulation et ne suffit pas à préciser le déficit [S3, S22].</p><p>Le cortisol participe à la réponse au stress, au maintien du glucose et à la réponse vasculaire. Son déficit expose à l’hypoglycémie, à l’asthénie et au collapsus. L’aldostérone favorise la rétention rénale de sodium et l’excrétion de potassium : son insuffisance provoque pertes hydrosodées, hypovolémie, rénine élevée et hyperkaliémie. L’excès d’androgènes explique virilisation fœtale 46,XX, maturation osseuse accélérée et pubarche précoce [S3].</p><p>Ces associations ne sont pas des lois universelles de E25 : l’accumulation de désoxycorticostérone dans certains déficits exerce au contraire un effet minéralocorticoïde et peut élever la pression. La biochimie précède donc l’attribution d’une perte de sel à toute forme rare [S3, S11].</p>''','Le déficit en cortisol explique la vulnérabilité au stress ; le profil minéralocorticoïde distingue perte de sel et hypertension [S3].'))
S.append(sec(5,'Étiologies et diagnostics voisins',table(['Hypothèse','Indices discriminants','Suite utile'],[['Déficit en 21-hydroxylase','17-hydroxyprogestérone et précurseurs, hyperandrogénie ± perte de sel','Profil stéroïdien puis CYP21A2 spécialisé.'],['Déficit en 11β-hydroxylase','Hyperandrogénie, hypertension possible, 11-désoxycortisol','Profil incluant désoxycorticostérone ; CYP11B1.'],['Déficit en 17α-hydroxylase/17,20-lyase','Déficit sexuel et hypertension/hypokaliémie possibles','Profil spécialisé ; CYP17A1.'],['Autres déficits : HSD3B2, POR, StAR, CYP11A1','Perte de sel ou variations du développement, profils variables ; signes squelettiques possibles avec POR','Pas de diagnostic sur un dosage isolé ; centre spécialisé.'],['Ovaires polykystiques ou autre cause ovarienne','Hirsutisme/troubles des règles sans preuve du déficit congénital','Exclure les causes pertinentes selon chronologie et profil.'],['Tumeur surrénale/ovarienne, exposition androgénique','Installation rapide, progression marquée, exposition ou masse','Bilan orienté ; aucune attribution automatique à E25.8.']])+'''<p>Une virilisation rapide, une hypertension sévère ou une discordance entre signes et dosage demandent de réexaminer l’hypothèse. Les infections, maladies rénales, anomalies digestives ou autres causes d’hypoglycémie restent des différentiels d’un nourrisson en mauvais état. Le sepsis et la crise surrénalienne peuvent nécessiter une prise en charge simultanée [S3, S4, S21].</p>''','L’hypertension avec excès androgénique fait chercher une autre voie que la seule 21-hydroxylase. Les tumeurs et les ovaires polykystiques gardent leur diagnostic propre [S3].'))
S.append(sec(6,'Anamnèse et communication','''<p>Chez le nourrisson, préciser alimentation, vomissements, poids de naissance et évolution pondérale, urines, fièvre, état général, dépistage et traitements reçus. Chercher un antécédent familial de déficit enzymatique, de consanguinité ou de décès néonatal inexpliqué avec tact. Un dépistage négatif ou en attente ne clôt pas l’enquête si le tableau est grave [S3, S9, S21].</p><p>Chez l’enfant, documenter courbe de croissance, âge de pubarche, progression, développement pubertaire et âge osseux antérieur. Chez l’adulte, préciser chronologie de l’hirsutisme/acné, cycles, désir de grossesse, fertilité et changements rapides. Les signes n’ont pas la même signification selon leur vitesse d’apparition [S3, S4].</p><p>Pour toute personne traitée, relever le produit exact, dose, horaires, prise réelle, vomissements, maladies récentes, interventions, médicaments inducteurs/inhibiteurs et accès au traitement. Demander si le patient possède une carte, un plan de maladie et un kit injectable utilisable, et s’il sait qui appeler [S10, S14, S21].</p><p>Aborder intimité, image corporelle, sexualité et difficultés familiales sans présumer identité de genre ou orientation. Expliquer le but de tout examen génital ; respecter consentement, confidentialité et possibilité d’accompagnement. Les comportements ou attirances ne sont pas des symptômes à corriger [S3].</p>''','La chronologie, la croissance et l’accès réel au remplacement sont aussi importants que l’étiquette génétique [S3, S21].'))
S.append(sec(7,'Examen clinique et sémiologie',f'''<p data-semiology-clinical="E25">La sémiologie relie chaque signe à une hypothèse et à une action. Mesurer constantes, perfusion, hydratation, conscience, poids et croissance ; examiner la pression avec une technique et des références adaptées à l’âge. L’hyperpigmentation peut orienter vers une stimulation corticotrope primaire sans être constante ni spécifique [S3, S21].</p><p>Un nourrisson peut présenter seulement mauvaise alimentation, vomissements, perte pondérale et somnolence avant le choc. Un enfant peut grandir vite initialement, mais perdre du potentiel de taille par maturation osseuse accélérée. À l’inverse, ralentissement statural avec prise pondérale sous traitement évoque notamment un excès glucocorticoïde [S3].</p><p>L’examen des organes génitaux, s’il est indiqué, est expliqué et limité aux besoins cliniques. L’aspect externe seul ne détermine ni les chromosomes, ni les organes internes, ni l’identité future. Les examens répétés et photographies sans nécessité peuvent nuire. L’examen testiculaire ne suffit pas à exclure de petites inclusions surrénaliennes ; une échographie a sa place selon le suivi spécialisé [S3].</p><p>Les neuf volets de {w('semio','sémiologie : normal, signes et limites')} détaillent cette démarche. Aucune performance diagnostique chiffrée du seul examen clinique n’est inventée.</p>''','Une anatomie externe apparemment habituelle ne rassure pas sur le cortisol. La croissance rapide et la petite taille finale peuvent relever du même excès androgénique [S3].'))
S.append(sec(8,'Diagnostic positif et séquence d’exploration','''<p>La démarche commence par la sécurité : si crise suspectée, traitement urgent et prélèvements sans retard. Hors urgence, on précise âge, tableau, traitement et résultat du dépistage avant de choisir le profil biologique. Un dépistage néonatal élevé n’est pas à lui seul une confirmation, particulièrement chez le prématuré ou le nouveau-né malade [S3, S21].</p><p>Le dosage de 17-hydroxyprogestérone est central pour le déficit en 21-hydroxylase. Les immunodosages peuvent réagir avec d’autres stéroïdes ; la spectrométrie de masse et un profil de plusieurs précurseurs améliorent la spécificité. Les seuils dépendent du prélèvement, de l’âge, de la méthode, de la prématurité et du stress. La prise de glucocorticoïdes modifie les valeurs [S3].</p><p>Pour une forme non classique, le seuil basal historique de 6 nmol/L (2 ng/ml) oriente vers une stimulation lorsque le laboratoire ne dispose pas de seuil local plus pertinent. Une valeur basale ou stimulée de 30 nmol/L (10 ng/ml) soutient le diagnostic dans les études anciennes. Ces chiffres ne sont pas un seuil universel moderne transférable à tout immunodosage ou toute méthode de masse [S4, S5].</p><p>La stimulation au tétracosactide et le génotypage sont interprétés avec le profil complet. La FI du test de réserve cortisolaire et les critères stéroïdiens de l’hyperplasie répondent à des questions différentes. Le génotypage spécialisé recherche variants et nombre de copies, avec analyse parentale si nécessaire ; un panel limité négatif peut manquer une anomalie [S18, S22].</p>''','Dépister, confirmer le déficit et évaluer la réserve cortisolaire sont des questions distinctes ; le seuil garde sa méthode [S3, S4, S18].'))
S.append(sec(9,'Drapeaux rouges et crise surrénalienne','''<p>Hypotension ou mauvaise perfusion, déshydratation, troubles de conscience, convulsions, hypoglycémie et troubles du sodium/potassium imposent une prise en charge urgente. Une infection avec vomissements peut empêcher l’absorption du traitement oral. Une kaliémie normale n’exclut pas une insuffisance en cortisol et une pression encore conservée n’exclut pas la déplétion [S3, S21].</p>'''+table(['Repère européen BSPED 2023','Dose initiale hydrocortisone','Portée'],[['Moins d’un an','25 mg IM ou IV','Option pratique par âge ; pas 100 mg systématique au nouveau-né.'],['1–5 ans','50 mg IM ou IV','Suite hospitalière selon réponse et protocole.'],['Dès 6 ans','100 mg IM ou IV','Pas le traitement d’entretien.'],['Option au poids, enfant >28 jours corrigés','2 mg/kg IV, maximum 100 mg','Alternative, pas ajout au bolus par âge.'],['Nouveau-né <28 jours corrigés','4 mg/kg IV','Option hospitalière au poids ; suite et réévaluation spécialisées.']])+'''<p>La voie veineuse ne doit pas retarder l’injection intramusculaire disponible selon le plan. Le consensus associe contrôle/correction du glucose, remplissage adapté et surveillance répétée. Son tableau propose en choc un bolus de chlorure de sodium 0,9 % de 10 ml/kg avec réévaluation ; en glycémie &lt;3 mmol/L, glucose 10 % 2 ml/kg IV et contrôle à quinze minutes. Ce sont des repères de protocole pédiatrique hospitalier, pas une autorisation de n’importe quel produit ou un protocole autonome à domicile [S21].</p><p>La famille applique son plan injectable et sollicite immédiatement l’aide urgente ; elle ne reste pas à domicile après une injection pour une décompensation grave. Les prélèvements diagnostiques ne retardent pas l’hydrocortisone. La suite, les fluides, les électrolytes et la cause demandent une équipe expérimentée ; des adolescents pris en charge par un service adulte peuvent relever du protocole adulte local [S16, S21].</p>''','La dose de crise dépend de l’âge/poids et du contexte. Après l’injection de secours, l’évaluation urgente et la surveillance restent indispensables [S21].'))
S.append(sec(10,'Prise en charge : remplacer sans surtraiter',f'''<p>Le traitement classique remplace le cortisol indispensable et contrôle autant que possible l’excès androgénique, avec minéralocorticoïde si le profil l’exige. Le suivi cherche un équilibre : l’insuffisance expose à la crise et à l’excès androgénique ; une dose excessive compromet croissance, poids, pression, os et métabolisme. La normalisation complète de tous les précurseurs n’est pas l’objectif automatique [S3].</p><p>L’hydrocortisone est privilégiée chez l’enfant en croissance. La FI {w('alkindi','Alkindi')} décrit, pour l’hyperplasie, 10–15 mg/m²/j en trois ou quatre prises de la naissance à moins de dix-huit ans. {w('galepharm','Hydrocortisone Galepharm')} et {w('solucortef','Solu-Cortef')} ont leurs formes et indications propres. Un comprimé, des granulés et une injection ne s’interchangent pas sans vérifier dose délivrée, dispositif et suivi [S14–S16].</p><p>Le minéralocorticoïde est ajusté à la pression, aux électrolytes, à la rénine et à la situation clinique. La FI {w('florinef','Florinef')} mars 2026 indique 2–5 µg/kg/j pour 0–12 ans ; la revue spécialisée cite chez le nourrisson 100–200 µg/j, parfois davantage en résistance rénale néonatale. Ces repères peuvent différer fortement : ils sont affichés séparément, sans fabriquer une dose moyenne. Le centre pédiatrique et la pharmacie doivent vérifier le schéma, le produit et sa justification [S3, S17].</p><p>Une forme non classique asymptomatique ne nécessite pas systématiquement de glucocorticoïde. Symptômes, croissance et fertilité orientent une décision individualisée ; un traitement peut lui-même supprimer l’axe et créer un besoin de couverture de stress. Les traitements de l’hirsutisme ont leurs indications et risques propres, sans ordonnance de classe improvisée ici [S3–S5].</p>''','Le remplacement classique est indispensable ; le traitement non classique dépend des conséquences. La dose se juge avec la croissance et la clinique, jamais un marqueur seul [S3].'))
S.append(sec(11,'Complications, pronostic et suivi','''<p>Le suivi mesure croissance, vitesse staturale, poids, pression, puberté, signes de sous-traitement et d’excès glucocorticoïde. Les prélèvements hormonaux doivent garder un horaire comparable par rapport au médicament, avec méthode connue. L’hormone corticotrope seule n’est pas une cible de titration validée ; vouloir supprimer tous les précurseurs peut provoquer un surtraitement [S3].</p><p>Chez le petit enfant, les visites sont rapprochées ; la revue propose au moins tous les trois mois avant dix-huit mois puis environ tous les quatre à six mois chez l’enfant plus âgé, avec adaptation lors d’un changement. La FI Alkindi souligne aussi le suivi fréquent de croissance. Les intervalles de synthèse ne remplacent pas les besoins du patient [S3, S14].</p><p>Une maturation osseuse accélérée peut réduire la taille adulte. Obésité, hypertension, troubles métaboliques et fragilité osseuse sont recherchés selon exposition et risque. Les inclusions surrénaliennes testiculaires sont habituellement bénignes mais peuvent altérer les tubes et la fertilité ; l’échographie est plus sensible que la palpation pour les petites lésions. Ni la bilatéralité ni l’imagerie seules n’excluent toute tumeur d’une autre nature [S3, S11].</p><p>La fertilité peut être préservée, mais son évaluation ne se résume pas à un dosage. Le suivi aborde cycles, projet parental, fonction gonadique, accès au conseil génétique et éventuelle conservation de sperme selon lésions. Le pronostic bénéficie du dépistage et des soins ; le risque de crise persiste malgré un diagnostic précoce [S3, S9].</p>''','Suivre croissance, pression, hormones contextualisées et vécu. Un dépistage réussi n’annule pas le risque de crise ni les besoins à l’âge adulte [S3].'))
S.append(sec(12,'Maladie intercurrente, grossesse et transition','''<p>Le patient reçoit un plan écrit de maladie, une carte et un kit injectable avec formation pratique de l’entourage. La FI Alkindi décrit doublement ou triplement transitoire lors de stress léger selon le plan ; BSPED propose un total oral d’environ 30 mg/m²/j en quatre prises pour ses épisodes de maladie. Ce sont des approches distinctes, pas deux augmentations à cumuler [S14, S21].</p><p>Vomissements empêchant la prise, détérioration ou stress majeur imposent relais parentéral et évaluation urgente. Le consensus précise de ne pas augmenter automatiquement la fludrocortisone pendant la maladie ; l’effet minéralocorticoïde des fortes doses d’hydrocortisone et les fluides peuvent couvrir temporairement le besoin, avec reprise orale quand possible. Le plan spécialisé décide [S21].</p><p>La grossesse demande maintien du remplacement nécessaire, suivi endocrino-obstétrical et adaptation au contexte. La FI Florinef exige une nécessité démontrée et interdit l’allaitement pendant ce produit, tandis que la FI Alkindi permet la substitution hydrocortisonée avec précautions. Ces formulations et avertissements ne sont pas harmonisés par supposition [S14, S17].</p><p>Le traitement fœtal prénatal par dexaméthasone reste expérimental dans les sources ; risques, effets à long terme et enjeux éthiques empêchent une prescription routinière. Le diagnostic génétique prénatal est une démarche distincte [S3, S22]. La transition vers les soins adultes prépare autonomie, renouvellements, maladie, études/voyages et projet parental sans rupture de remplacement [S3, S10].</p>''','Le plan de stress s’écrit avant la maladie et ne cumule pas aveuglément des schémas. La transition doit conserver un accès continu au traitement [S14, S21].'))
codes=[]
def rec(v):
 if isinstance(v,dict):
  if str(v.get('code','')).startswith('E25'):codes.append(v)
  for x in v.values():rec(x)
 elif isinstance(v,list):
  for x in v:rec(x)
rec(json.loads((R/'nosology/fragments/S05.json').read_text()))
S.append(sec(13,'Tous les sous-codes et contexte suisse',table(['Code local OFS 2024','Libellé'],[[x['code'],html.escape(x['title'])] for x in codes])+'''<p>E25.0 est le parent des déficits enzymatiques congénitaux. E25.00 et E25.01 distinguent les formes classique et tardive de déficit en 21-hydroxylase. Les autres déficits enzymatiques congénitaux relèvent du groupe E25.08 s’ils sont précisés ; l’absence d’information enzymatique ne justifie pas d’inventer un gène. E25.8 et E25.9 conservent leurs libellés, sans absorber toute hyperandrogénie ou toute variation du développement [S1].</p><p>Le dépistage néonatal suisse et le parcours spécialisé constituent le contexte de soins. Le remboursement d’un produit, sa disponibilité à la date d’une prescription, les règles de génétique et les décisions chirurgicales individuelles exigent une vérification actuelle. Aucune autorisation suisse 2026 du crinecerfont n’est établie par les essais lus ; une recherche de nom sans résultat ne démontre pas son absence réglementaire [S8, S9, S12, S13, S22].</p><p>La prise en charge génitale distingue urgence fonctionnelle et décision irréversible élective. Information, temps de discussion, autonomie et consentement sont essentiels ; les références à la loi allemande dans une brochure ne deviennent pas une règle suisse [S3, S10].</p>''','Le code suit le diagnostic documenté. Aucun statut de remboursement ou de traitement génital individuel n’est déduit du seul libellé [S1].'))
S.append(sec(14,'Critères, paramètres et pièges fédéraux','''<p><b>Critères formels.</b> Le déficit en 21-hydroxylase se construit sur le tableau, le profil hormonal et la confirmation moléculaire adaptée, avec distinction classique/non classique. Le dépistage seul ne suffit pas ; une crise reste clinique et ne doit pas attendre ces critères [S3, S22].</p><p><b>Paramètres à garder avec leurs unités.</b> Les seuils historiques non classiques de 6 et 30 nmol/L concernent la 17-hydroxyprogestérone, pas le cortisol. La FI Synacthen mesure le cortisol avant et à trente minutes ; ses seuils historiques ne sont pas un seuil de 17-hydroxyprogestérone. Les doses d’hydrocortisone en mg/m²/j ne sont pas des mg/kg par injection ; les microgrammes de fludrocortisone ne sont pas des milligrammes [S4, S14, S17, S18].</p><p><b>Pièges.</b> Donner 100 mg à chaque nouveau-né sans référentiel ; rassurer sur les organes génitaux d’un garçon ; étiqueter un prématuré sur un dépistage isolé ; confondre seuil de dépistage et confirmation ; normaliser la 17-hydroxyprogestérone au prix d’un Cushing ; tripler la fludrocortisone avec l’hydrocortisone ; interrompre une substitution indispensable ; traiter toute forme non classique asymptomatique ; affirmer qu’une imagerie testiculaire suffit à tout distinguer [S3, S21].</p><p>L’examen évalue la capacité à expliquer mécanisme, gravité, choix du test et conduite, avec respect de l’intimité et des incertitudes. Aucun score pronostique E25 unique ni question fédérale garantie n’est inventé [S20].</p>''','Le bon chiffre répond à une question, une méthode, un âge et une voie. Les unités et la population font partie de la réponse [S14, S17, S21].'))
head='<template id="ch-E25"><div class="chap"><style>.e25-fig{position:relative}.e25-fig img{display:block;max-width:100%;height:auto}.e25-pin{position:absolute;background:#123d4e;color:white;border:2px solid white;border-radius:50%;padding:1px 4px;font-weight:bold;font-size:clamp(8px,1vw,12px);line-height:1.2}.e25-p1{left:9%;top:40%}.e25-p2{left:14%;top:57%}.e25-p3{left:39%;top:30%}.e25-p4{left:56%;top:58%}[data-e25-table="1"]{display:block;max-width:100%;overflow-x:auto}[data-e25-table="1"] th,[data-e25-table="1"] td{min-width:9em}</style><div class="chap-head"><div class="code">E25 · E25.00–E25.9 · Endocrinologie et métabolisme</div><h1>Anomalies génito-surrénaliennes</h1><span class="status">Relecture Sol du 2 novembre 2026 · Sources suisses et européennes · Auto-relecture, sans validation médicale humaine</span></div><div class="tabs ui" role="tablist">'
for i,(p,t) in enumerate([('pA','Pathologie et prise en charge'),('pE','Examens complémentaires'),('pS','Sciences fondamentales spécialisées'),('pP','Pharmacologie')]):head+=f'<button role="tab" aria-controls="{p}" data-p="{p}" aria-selected="{str(i==0).lower()}">{t}</button>'
