def cite(m):
 ids=[]
 for chunk in m[1].split(','):
  nums=re.findall(r'S?(\d+)',chunk)
  if ('–' in chunk or '—' in chunk) and len(nums)==2: ids.extend('S'+str(i) for i in range(int(nums[0]),int(nums[1])+1))
  else:ids.extend('S'+n for n in nums)
 ids=list(dict.fromkeys(i for i in ids if i in source_by_id))
 return '['+', '.join(f'<a data-reference-source="1" href="{html.escape(source_by_id[i]["url"],quote=True)}" target="_blank" rel="noopener">{i}</a>' for i in ids)+']' if ids else m[0]
for p in (R/'chapters/E25').glob('*.html'):
 text=p.read_text();chunks=[];inside=0
 for x in re.split(r'(<[^>]+>)',text):
  if x.startswith('<'):
   if re.match(r'<a(?:\s|>)',x):inside+=1
   elif x.startswith('</a'):inside=max(0,inside-1)
   chunks.append(x)
  else:chunks.append(x if inside else re.sub(r'\[((?:S\d+)[^\[\]]*)\]',cite,x))
 text=''.join(chunks);text=re.sub(r'(</(?:p|section|table|template|figure|nav)>)(?=<)',r'\1\n',text);p.write_text(text)
