   if inlocal:x=pat.sub(lambda m:'<a data-reference-source="1" href="'+source_by_id['S22' if termmap[m[1]]=='genes' else ('S1' if termmap[m[1]]=='nosologie' else ('S14' if termmap[m[1]]=='metabolisme' else 'S3'))]['url']+'" target="_blank" rel="noopener">'+m[1]+'</a>',x)
   else:x=pat.sub(lambda m:w(termmap[m[1]],m[1]),x)
